// ==== 讀入（Webhook 可能把資料放在 body）====
const payload   = $json.body ?? $json;
const root      = Array.isArray(payload) ? payload[0] : (payload || {});
const frames    = Array.isArray(root.frames) ? root.frames : [];
const elder_id  = root.elder_id ?? "";
const session_id= root.session_id ?? "";

// ==== 小工具 ====
const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
const dist=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
const mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2];
const cxwhToXYXY = (b)=>[b.cx-b.w/2, b.cy-b.h/2, b.cx+b.w/2, b.cy+b.h/2];
const boxCenter  = (xyxy)=>[(xyxy[0]+xyxy[2])/2,(xyxy[1]+xyxy[3])/2];
const boxW=(b)=>b[2]-b[0], boxH=(b)=>b[3]-b[1];
const iou=(a,b)=>{const x1=Math.max(a[0],b[0]),y1=Math.max(a[1],b[1]),x2=Math.min(a[2],b[2]),y2=Math.min(a[3],b[3]);
  const iw=Math.max(0,x2-x1), ih=Math.max(0,y2-y1), inter=iw*ih; if(!inter) return 0;
  const areaA=boxW(a)*boxH(a), areaB=boxW(b)*boxH(b), uni=areaA+areaB-inter; return uni>0? inter/uni : 0; };
const getKP=(kps,i)=>{const p=kps?.[i]; if(!p) return null;
  if(Array.isArray(p)) return [p[0],p[1]];
  if(p?.x!=null && p?.y!=null) return [p.x,p.y];
  return null;};
const angleStable=(a,b,c)=>{ if(!a||!b||!c) return null;
  const ux=a[0]-b[0], uy=a[1]-b[1], vx=c[0]-b[0], vy=c[1]-b[1];
  const dot=ux*vx+uy*vy, cross=ux*vy-uy*vx;
  return +(Math.atan2(Math.abs(cross),dot)*180/Math.PI).toFixed(1); };
const torsoTiltDeg=(kps)=>{ const L_SH=getKP(kps,5), R_SH=getKP(kps,6), L_H=getKP(kps,11), R_H=getKP(kps,12);
  if(!L_SH||!R_SH||!L_H||!R_H) return null; const sh=mid(L_SH,R_SH), hip=mid(L_H,R_H);
  const vx=sh[0]-hip[0], vy=sh[1]-hip[1], mag=Math.hypot(vx,vy)||1; const cos=clamp((-vy)/mag,-1,1);
  return +(Math.acos(cos)*180/Math.PI).toFixed(1); };

// ==== 取 pose / object 幀 ====
const poseF   = frames.find(f => f?.type==='pose'   || f?.persons);
const objectF = frames.find(f => f?.type==='object' || f?.detections);

// 影像資訊
const W = (poseF?.image_size?.width  ?? objectF?.image_size?.width  ?? 640);
const H = (poseF?.image_size?.height ?? objectF?.image_size?.height ?? 480);
const diag = Math.hypot(W,H);
const frame_id     = poseF?.frame_id ?? objectF?.frame_id ?? null;
const timestamp_ms = poseF?.timestamp_ms ?? objectF?.timestamp_ms ?? null;

// ==== 人框 / KPs ====
let person=null, kps=null, personBoxXYXY=null;
if (poseF?.persons?.length){
  const p=poseF.persons[0];
  if (p.bbox){
    personBoxXYXY=cxwhToXYXY(p.bbox);
    person={ box: personBoxXYXY, center:[+p.bbox.cx.toFixed(2), +p.bbox.cy.toFixed(2)],
             w:+(p.bbox.w).toFixed(2), h:+(p.bbox.h).toFixed(2), conf: p.score ?? null };
  }
  if (Array.isArray(p.keypoints)) kps=p.keypoints;
}

// === 單幀姿態特徵（新增） ===
let torso_tilt=null, left_knee=null, right_knee=null, height_norm=null, ankle_gap_norm=null;
let com=null, kp_coverage=null, kp_mean_conf=null;
let bbox_w_norm=null, bbox_h_norm=null, head_y_norm=null, hip_y_norm=null;

if (person && kps){
  torso_tilt = torsoTiltDeg(kps);

  const L_H=getKP(kps,11), L_K=getKP(kps,13), L_A=getKP(kps,15);
  const R_H=getKP(kps,12), R_K=getKP(kps,14), R_A=getKP(kps,16);
  left_knee  = angleStable(L_H,L_K,L_A);
  right_knee = angleStable(R_H,R_K,R_A);

  const L_SH=getKP(kps,5), R_SH=getKP(kps,6);
  if (L_SH && R_SH && L_A && R_A){
    const seg = dist( mid(L_SH,R_SH), mid(L_A,R_A) );
    height_norm = person.h>0 ? +(clamp(seg/person.h,0,1)).toFixed(3) : null;
    ankle_gap_norm = person.w>0 ? +(dist(L_A,R_A)/person.w).toFixed(3) : null;
  }

  // COM + 量測品質
  let n=0, sx=0, sy=0, sc=0, validKP=0;
  for (const q of kps){
    const pt = Array.isArray(q) ? q : (q?.x!=null ? [q.x,q.y] : null);
    const cf = (q?.confidence ?? q?.c ?? 1);
    if (pt && Number.isFinite(pt[0]) && Number.isFinite(pt[1])){
      n++; sx+=pt[0]; sy+=pt[1]; sc += (Number.isFinite(cf)? cf: 0);
      if (cf>=0.5) validKP++;
    }
  }
  if (n>0){
    com = [ +(sx/n).toFixed(2), +(sy/n).toFixed(2) ];
    kp_mean_conf = +(sc/n).toFixed(3);
    kp_coverage  = +(validKP / n).toFixed(3);
  }

  // bbox 與畫面比例、頭/髖高度
  bbox_w_norm = +(person.w / W).toFixed(3);
  bbox_h_norm = +(person.h / H).toFixed(3);
  const head=getKP(kps,0);
  const hipMid = (L_H && R_H) ? mid(L_H,R_H) : null;
  if (head)   head_y_norm = +(head[1]   / H).toFixed(3);
  if (hipMid) hip_y_norm  = +(hipMid[1] / H).toFixed(3);
}

// === 場景幾何（與 bed/chair/sofa 的距離與 IoU） ===
let iou_bed=0, iou_chair=0, iou_sofa=0;
let dist_bed=null, dist_chair=null, dist_sofa=null;
let near_object=null, near_d=null;

const MAIN = new Set(['bed','chair','sofa']);
if (objectF?.detections?.length && person){
  const pc = person.center;
  let best=Infinity, bestName=null;
  for (const d of objectF.detections){
    if (!MAIN.has(d.cls_name)) continue;
    const obXY=cxwhToXYXY(d.bbox), oc=[d.bbox.cx, d.bbox.cy];
    const dn = +( (Math.hypot(oc[0]-pc[0], oc[1]-pc[1]) / diag).toFixed(3) );
    const iv = +(iou(person.box, obXY).toFixed(3));

    if (d.cls_name==='bed'){ iou_bed=iv; dist_bed=dn; }
    if (d.cls_name==='chair'){ iou_chair=iv; dist_chair=dn; }
    if (d.cls_name==='sofa'){ iou_sofa=iv; dist_sofa=dn; }

    if (dn < best){ best=dn; bestName=d.cls_name; }
  }
  if (bestName){ near_object=bestName; near_d=+best.toFixed(3); }
}

// === relations（維持你原本的輸出習慣） ===
const relations=[];
function pushRel(name, dn, iv){
  if (dn==null && iv==null) return;
  const onThr = (name==='bed') ? 0.15 : 0.20;
  const nearThr = 0.18;
  let relation='far';
  if ((iv ?? 0) >= onThr) relation='on';
  else if ((dn ?? 1) <= nearThr) relation='beside';
  relations.push({ object:name, distance_norm:dn ?? null, iou:iv ?? 0, relation });
}
pushRel('bed', dist_bed, iou_bed);
pushRel('chair', dist_chair, iou_chair);
pushRel('sofa', dist_sofa, iou_sofa);

// === Fallback 粗判（提供給前端或 Agent 參考） ===
const kneesMin = Math.min( left_knee ?? 999, right_knee ?? 999 );
let status_fallback='unknown';
if (height_norm!=null && torso_tilt!=null){
  if (height_norm>0.75 && torso_tilt<25 && iou_bed<0.15 && kneesMin>150) status_fallback='standing';
  else if (height_norm>=0.45 && height_norm<=0.70 && kneesMin<120)      status_fallback='sitting';
  else if ((height_norm<0.40 && torso_tilt>50) || iou_bed>0.15)          status_fallback='lying';
  else status_fallback='transition';
}
const near_fallback = near_object || ((iou_bed>0.15) ? 'bed' : 'none');
const isDangrous_fallback = false; // 單幀不判跌倒；要用時間窗訊號（Δheight/Δtilt）才可靠

// === 組輸出（給 Agent 超好消化，也保留你原本的欄位） ===
return {
  json: {
    elder_id,
    session_id,
    frame: { frame_id, timestamp_ms, image_size:{ width:W, height:H } },

    person: person || null,
    features: {
      torso_tilt, height_norm, left_knee, right_knee, ankle_gap_norm,
      com, kp_coverage, kp_mean_conf,
      bbox_w_norm, bbox_h_norm, head_y_norm, hip_y_norm
    },
    scene: {
      near_object, near_d,
      iou_bed, iou_chair, iou_sofa,
      dist_bed, dist_chair, dist_sofa
    },

    // 舊格式相容
    person_center: person?.center || null,
    relations,

    // 簡易回退（可直接給前端用；最終還是建議讓 Agent 產生正式判斷）
    status_fallback: status_fallback,
    isDangrous_fallback: isDangrous_fallback,
    near_fallback: near_fallback,

    // 給 Agent 的輸出約束
    expect_output_schema: {
      status: "standing|sitting|lying|falling|transition|unknown",
      isDangrous: "boolean",
      near: "bed|chair|sofa|none"
    }
  }
};

// 1) 取請求攜帶的歷史 window（可能為空）
const reqWindow = Array.isArray($json.window) ? $json.window : [];

// 2) 把本幀轉成精簡記錄，推進 window，裁成最多 20 幀
const r = $json;
const nowRec = {
  ts: r.frame?.timestamp_ms ?? Date.now(),
  height_norm: r.features?.height_norm ?? null,
  torso_tilt:  r.features?.torso_tilt  ?? null,
  knees_min: Math.min(r.features?.left_knee ?? 999, r.features?.right_knee ?? 999),
  com_y: Array.isArray(r.features?.com) ? r.features.com[1] : null,
  iou_bed: r.scene?.iou_bed ?? 0,
  near_object: r.scene?.near_object ?? null
};
const windowArr = [...reqWindow, nowRec]
  .sort((a,b)=>a.ts-b.ts)
  .slice(-20);

// 3) 產生 last5 / prev5 / last3 / prev3
const takeLast = (arr,n)=>arr.slice(-Math.min(n,arr.length));
const last5 = takeLast(windowArr,5);
const prev5 = windowArr.slice(-10,-5);
const last3 = takeLast(windowArr,3);
const prev3 = windowArr.slice(-6,-3);

const mean = (arr, sel) => {
  const v = arr.map(sel).filter(x=>Number.isFinite(x));
  return v.length ? +(v.reduce((s,x)=>s+x,0)/v.length).toFixed(3) : null;
};
const diffMean = (a1,a2,sel)=>{
  if(!a1.length||!a2.length) return null;
  return +(mean(a1,sel) - mean(a2,sel)).toFixed(3);
};

// 4) 指標
const height_mean = mean(last5, r=>r.height_norm);
const tilt_mean   = mean(last5, r=>r.torso_tilt);
const knees_mean  = mean(last5, r=>r.knees_min);
const dHeight     = diffMean(last5, prev5, r=>r.height_norm);
const dTilt       = diffMean(last5, prev5, r=>r.torso_tilt);
const dHeight3    = diffMean(last3, prev3, r=>r.height_norm);
const dTilt3      = diffMean(last3, prev3,  r=>r.torso_tilt);

// 即時重心速度
let vy_now = null;
if (windowArr.length >= 2) {
  const a = windowArr[windowArr.length-2];
  const b = windowArr[windowArr.length-1];
  if (Number.isFinite(a.com_y) && Number.isFinite(b.com_y)) {
    const dt = (b.ts - a.ts) || 1;
    vy_now = +((b.com_y - a.com_y) / dt).toFixed(4); // px/ms
  }
}
const last = windowArr[windowArr.length-1] || {};
const scene = { near_object: last.near_object ?? null, iou_bed: last.iou_bed ?? 0 };

// 5) Hints（同之前）
const hint_stand = (height_mean!=null && tilt_mean!=null)
  ? (height_mean>0.75 && tilt_mean<30 && (knees_mean??151)>150 && scene.iou_bed<0.15) : false;
const hint_sit = (height_mean!=null && knees_mean!=null)
  ? (height_mean>=0.45 && height_mean<=0.70 && knees_mean<120) : false;
const hint_lie = (height_mean!=null && tilt_mean!=null)
  ? ((height_mean<0.40 && tilt_mean>50) || scene.iou_bed>0.15) : false;

const fast_drop_now  = ((dHeight3!=null && dTilt3!=null) && (dHeight3<=-0.18 && dTilt3>=+25) && scene.iou_bed<0.15)
                    || (vy_now!=null && vy_now>=0.04);
const fast_drop_long = (dHeight!=null && dTilt!=null) && (dHeight<=-0.30 && dTilt>=+40) && (scene.iou_bed<0.15);

// 6) 輸出：保留 window（回傳給父流程/前端/後端，下次請求直接帶回來）
return {
  json: {
    ...$json,
    window: windowArr,   // <<--- 下次請求請把它帶回來（最多 20 筆）
    summary: {
      window: { size: windowArr.length, last_block: last5.length },
      features: {
        height_norm: { mean_last: height_mean, delta_vs_prev: dHeight, delta_vs_prev3: dHeight3 },
        torso_tilt:  { mean_last: tilt_mean,  delta_vs_prev: dTilt,   delta_vs_prev3: dTilt3 },
        knees_min_mean: knees_mean,
        vy_now
      },
      scene,
      hints: { stand: hint_stand, sit: hint_sit, lie: hint_lie, fast_drop_now, fast_drop_long }
    }
  }
};
